from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext


def vat_breakdown(lines: list[dict], mode: str) -> dict:
    if not isinstance(lines, list):
        raise ValueError('lines must be a list')
    if not isinstance(mode, str) or mode not in ('PER_LINE', 'PER_INVOICE'):
        raise ValueError('mode must be PER_LINE or PER_INVOICE')
    if len(lines) == 0:
        return {'net': Decimal('0.00'), 'vat': Decimal('0.00'), 'gross': Decimal('0.00'), 'by_rate': {}}
    parsed = []
    for line in lines:
        if not isinstance(line, dict):
            raise ValueError('each line must be a dict')
        if 'quantity' not in line or 'unit_net' not in line or 'vat_rate' not in line:
            raise ValueError('line missing required key')
        quantity = line['quantity']
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('quantity must be a positive int')
        unit_net_raw = line['unit_net']
        if not isinstance(unit_net_raw, str):
            raise ValueError('unit_net must be a string')
        try:
            unit_net = Decimal(unit_net_raw)
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('unit_net must be parseable by Decimal') from None
        if not unit_net.is_finite() or unit_net < 0:
            raise ValueError('unit_net must be finite and >= 0')
        if unit_net.as_tuple().exponent < -4:
            raise ValueError('unit_net must have at most 4 decimal places')
        vat_rate_raw = line['vat_rate']
        if not isinstance(vat_rate_raw, str):
            raise ValueError('vat_rate must be a string')
        try:
            vat_rate = Decimal(vat_rate_raw)
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('vat_rate must be parseable by Decimal') from None
        if not vat_rate.is_finite():
            raise ValueError('vat_rate must be finite')
        if vat_rate == Decimal('0'):
            rate_value = Decimal('0')
            rate_key = '0'
        elif vat_rate == Decimal('4'):
            rate_value = Decimal('4')
            rate_key = '4'
        elif vat_rate == Decimal('10'):
            rate_value = Decimal('10')
            rate_key = '10'
        elif vat_rate == Decimal('21'):
            rate_value = Decimal('21')
            rate_key = '21'
        else:
            raise ValueError('vat_rate must be one of 0, 4, 10 or 21')
        parsed.append((quantity, unit_net, rate_value, rate_key))
    cents = Decimal('0.01')
    hundred = Decimal('100')
    with localcontext() as ctx:
        precision = 50
        for quantity, unit_net, rate_value, rate_key in parsed:
            exponent = unit_net.as_tuple().exponent
            precision += len(unit_net.as_tuple().digits) + len(str(quantity)) + (exponent if exponent > 0 else 0)
        ctx.prec = max(28, precision)
        groups = {}
        if mode == 'PER_LINE':
            for quantity, unit_net, rate_value, rate_key in parsed:
                exact_net = Decimal(quantity) * unit_net
                line_net = exact_net.quantize(cents, rounding=ROUND_HALF_UP)
                line_vat = (line_net * rate_value / hundred).quantize(cents, rounding=ROUND_HALF_UP)
                if rate_key not in groups:
                    groups[rate_key] = {'rate': rate_value, 'net': Decimal('0.00'), 'vat': Decimal('0.00'), 'net_exact': Decimal('0')}
                groups[rate_key]['net'] += line_net
                groups[rate_key]['vat'] += line_vat
        else:
            for quantity, unit_net, rate_value, rate_key in parsed:
                if rate_key not in groups:
                    groups[rate_key] = {'rate': rate_value, 'net': Decimal('0.00'), 'vat': Decimal('0.00'), 'net_exact': Decimal('0')}
                groups[rate_key]['net_exact'] += Decimal(quantity) * unit_net
            for group in groups.values():
                group_net = group['net_exact'].quantize(cents, rounding=ROUND_HALF_UP)
                group_vat = (group_net * group['rate'] / hundred).quantize(cents, rounding=ROUND_HALF_UP)
                group['net'] = group_net
                group['vat'] = group_vat
        by_rate = {}
        total_net = Decimal('0.00')
        total_vat = Decimal('0.00')
        for rate_key, group in groups.items():
            net_q = group['net'].quantize(cents, rounding=ROUND_HALF_UP)
            vat_q = group['vat'].quantize(cents, rounding=ROUND_HALF_UP)
            gross_q = (net_q + vat_q).quantize(cents, rounding=ROUND_HALF_UP)
            by_rate[rate_key] = {'net': net_q, 'vat': vat_q, 'gross': gross_q}
            total_net += net_q
            total_vat += vat_q
        total_net_q = total_net.quantize(cents, rounding=ROUND_HALF_UP)
        total_vat_q = total_vat.quantize(cents, rounding=ROUND_HALF_UP)
        total_gross_q = (total_net_q + total_vat_q).quantize(cents, rounding=ROUND_HALF_UP)
        return {'net': total_net_q, 'vat': total_vat_q, 'gross': total_gross_q, 'by_rate': by_rate}
